import{at as e,it as t,n,vt as r}from"./chunks/framework.CH5tFBxi.js";import{c as i,l as a,u as o}from"./chunks/assets.B6tPA-kF.js";var s=JSON.parse(`{"title":"Menu","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"menu.md","filePath":"menu.md"}`),c={name:`menu.md`};function l(n,s,c,l,u,d){return r(),t(`div`,null,[...s[0]||=[e(`<h1 id="menu" tabindex="-1">Menu <a class="header-anchor" href="#menu" aria-label="Permalink to “Menu”">​</a></h1><p>The main entry points for using json0714 are only two: the context menu and keyboard shortcuts.<br> The design philosophy of json0714 is not to over-intervene in or intercept the browser&#39;s network requests, but only to be actively invoked when you need it.<br> json0714 can run on any page except the <code>New Tab</code> page.</p><h2 id="standard-context-menu" tabindex="-1">Standard context menu <a class="header-anchor" href="#standard-context-menu" aria-label="Permalink to “Standard context menu”">​</a></h2><p>Right-click anywhere in the browser to see the json0714 menu.<br> You can use the shortcuts shown in the menu to quickly access the corresponding functions without relying on mouse operations; I use keyboard shortcuts most of the time.</p><p><img src="`+o+`" alt="Standard context menu" width="874" height="735"></p><h3 id="format-current-page-json" tabindex="-1">Format current page JSON <a class="header-anchor" href="#format-current-page-json" aria-label="Permalink to “Format current page JSON”">​</a></h3><p>Use the content displayed on the current page as JSON input.</p><h3 id="format-json-from-clipboard" tabindex="-1">Format JSON from clipboard <a class="header-anchor" href="#format-json-from-clipboard" aria-label="Permalink to “Format JSON from clipboard”">​</a></h3><p>Use the content in the clipboard as JSON input.</p><h3 id="copy-json" tabindex="-1">Copy JSON <a class="header-anchor" href="#copy-json" aria-label="Permalink to “Copy JSON”">​</a></h3><p>Copy the formatted JSON in the current workspace.<br> The copy and paste functions greatly simplify the interaction flow between users and the extension, acting as a highway for improving efficiency.</p><h3 id="quick-view" tabindex="-1">Quick view <a class="header-anchor" href="#quick-view" aria-label="Permalink to “Quick view”">​</a></h3><p>In Quick view mode, each <code>[]</code> list node retains at most 3 data entries, making it easier to analyze extremely large JSON structures.</p><h3 id="lock" tabindex="-1">Lock <a class="header-anchor" href="#lock" aria-label="Permalink to “Lock”">​</a></h3><ul><li><strong>Lock current path</strong>: Exactly match the current page URL; afterward, when the browser visits that URL, the extension runs automatically.</li><li><strong>Lock current domain</strong>: Match the current page domain; afterward, when the browser visits that domain, the extension runs automatically.</li><li><strong>Unlock</strong>: Cancel the automatic running effect of the extension for the current URL or current domain.</li></ul><h3 id="key-sorting" tabindex="-1">Key sorting <a class="header-anchor" href="#key-sorting" aria-label="Permalink to “Key sorting”">​</a></h3><p>When formatting, automatically sort JSON keys in ASCII lexicographical order.<br> When <code>None</code> is selected, preserve the original input order.</p><h3 id="more-settings" tabindex="-1">More settings <a class="header-anchor" href="#more-settings" aria-label="Permalink to “More settings”">​</a></h3><p>Open the settings page; see the <code>Settings</code> chapter for details.</p><h2 id="selection-context-menu" tabindex="-1">Selection context menu <a class="header-anchor" href="#selection-context-menu" aria-label="Permalink to “Selection context menu”">​</a></h2><p>Right-click on selected text, and the menu will show json0714&#39;s context menu.<br> This capability is not limited to the json0714 workspace; it can be used on any webpage opened in Chrome.</p><p><img src="`+a+`" alt="Selection context menu" width="685" height="382"></p><h3 id="generate-qr-code" tabindex="-1">Generate QR code <a class="header-anchor" href="#generate-qr-code" aria-label="Permalink to “Generate QR code”">​</a></h3><p>Generate a QR code corresponding to the selected text and display it in a popup.<br> It is a bridge for transferring data from desktop to mobile.<br> The extension itself does not limit or validate the length of the selected text; it is recommended to keep it within 200 characters, as overly long text may cause an error.</p><h3 id="date-time-formatting" tabindex="-1">Date/time formatting <a class="header-anchor" href="#date-time-formatting" aria-label="Permalink to “Date/time formatting”">​</a></h3><p>Try to convert the selected text into the standard time format <code>yyyy-MM-dd HH:mm:ss</code> for easier reading, and display it in a popup.<br> The extension itself does not impose restrictions or validation on the selected text, supports multiple time formats, and gives a prompt when it fails.<br> If there is an unsupported time format, you are welcome to submit a request on <code>GitHub</code>.</p><h3 id="copy-selection-screenshot" tabindex="-1">Copy selection screenshot <a class="header-anchor" href="#copy-selection-screenshot" aria-label="Permalink to “Copy selection screenshot”">​</a></h3><p>Use the currently selected text area as the boundary to take a cross-screen screenshot within the browser. Compared with a long screenshot of the entire page, the granularity is finer, the purpose is more targeted, and it saves more resources.<br> Due to hard browser policy restrictions, the extension cannot access content in iframes, so screenshots targeting iframes will fail; in this case, it is recommended to use the <code>Open frame in new tab</code> feature provided by this extension. Open the embedded iframe in a new tab, and the iframe will naturally become a regular page, with no screenshot restrictions in the new tab.</p><h3 id="visit-selected-link" tabindex="-1">Visit selected link <a class="header-anchor" href="#visit-selected-link" aria-label="Permalink to “Visit selected link”">​</a></h3><p>Try to open the selected text as a link in a new tab.<br> The extension itself does not impose restrictions or validation on the selected text.</p><h3 id="download-selected-link" tabindex="-1">Download selected link <a class="header-anchor" href="#download-selected-link" aria-label="Permalink to “Download selected link”">​</a></h3><p>Try to download the selected text as a download link.<br> The extension itself does not impose restrictions or validation on the selected text.</p><h2 id="iframe-context-menu" tabindex="-1">Iframe context menu <a class="header-anchor" href="#iframe-context-menu" aria-label="Permalink to “Iframe context menu”">​</a></h2><p>Right-click within an iframe, and the menu will show json0714&#39;s iframe menu.</p><p><img src="`+i+`" alt="iframe context menu" width="743" height="337"></p><h3 id="open-frame-in-new-tab" tabindex="-1">Open frame in new tab <a class="header-anchor" href="#open-frame-in-new-tab" aria-label="Permalink to “Open frame in new tab”">​</a></h3><p>Open the embedded iframe in a new tab.</p>`,37)]])}var u=n(c,[[`render`,l]]);export{s as __pageData,u as default};